selector_to_html = {"a[href=\"#launch-metadata-hook\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Launch metadata hook<a class=\"headerlink\" href=\"#launch-metadata-hook\" title=\"Link to this heading\">#</a></h2><p>\u4f7f\u7528 <code class=\"docutils literal notranslate\"><span class=\"pre\">hook=\"triton\"</span></code> \u65f6\uff0cprofiler \u4f1a\u5728\u6bcf\u4e2a kernel \u542f\u52a8\u524d\u8c03\u7528 <code class=\"docutils literal notranslate\"><span class=\"pre\">launch_metadata</span></code> \u51fd\u6570\uff0c\u4ee5\u4fbf\u63d0\u4f9b\u9010 kernel \u7684\u5143\u6570\u636e\uff1a</p>", "a[href=\"#profile\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">\u5408\u5e76 profile<a class=\"headerlink\" href=\"#profile\" title=\"Link to this heading\">#</a></h3><p>\u591a\u4e2a\u4f7f\u7528\u4e0d\u540c\u540e\u7aef\u7684\u5e76\u53d1 session \u53ef\u4ee5\u5206\u6790\u540c\u4e00\u533a\u57df\uff0c\u518d\u7528 Hatchet \u5408\u5e76\u505a\u4e8b\u540e\u5206\u6790\uff1a</p>", "a[href=\"#id5\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u7ed3\u679c\u53ef\u89c6\u5316<a class=\"headerlink\" href=\"#id5\" title=\"Link to this heading\">#</a></h2><p>\u9ed8\u8ba4 profile \u4ee5 JSON \u5199\u51fa\uff0c\u53ef\u88ab <a class=\"reference external\" href=\"https://github.com/hatchet/hatchet\">Hatchet</a> \u8bfb\u53d6\uff08\u5b89\u88c5 <code class=\"docutils literal notranslate\"><span class=\"pre\">llnl-hatchet</span></code>\uff1b<code class=\"docutils literal notranslate\"><span class=\"pre\">hatchet</span></code> \u5305\u662f\u53e6\u4e00\u5957 API\uff09\uff1a</p>", "a[href=\"#id3\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">\u6307\u4ee4\u91c7\u6837<a class=\"headerlink\" href=\"#id3\" title=\"Link to this heading\">#</a></h3><p>NVIDIA GPU \u53ef\u901a\u8fc7 <code class=\"docutils literal notranslate\"><span class=\"pre\">cupti_pcsampling</span></code> \u4f7f\u7528\u6307\u4ee4\u91c7\u6837\uff1b\u7aef\u5230\u7aef\u5f00\u9500\u7ea6 20 \u500d\uff08\u4e3b\u8981\u6765\u81ea CPU \u4fa7\u4f20\u8f93\u4e0e\u5904\u7406\uff09\uff0c\u4f46\u5355\u4e2a kernel \u7684\u5f00\u9500\u53ef\u4ee5\u5ffd\u7565\u3002<code class=\"docutils literal notranslate\"><span class=\"pre\">flagtree-profiler-viewer</span></code> \u7684 <code class=\"docutils literal notranslate\"><span class=\"pre\">-i</span> <span class=\"pre\">&lt;regex&gt;</span> <span class=\"pre\">-d</span> <span class=\"pre\">&lt;depth&gt;</span> <span class=\"pre\">-t</span> <span class=\"pre\">&lt;threshold&gt;</span></code> \u9009\u9879\u53ef\u5e2e\u52a9\u8fc7\u6ee4\u5173\u6ce8\u7684 op\u3002</p>", "a[href=\"#id4\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u547d\u4ee4\u884c<a class=\"headerlink\" href=\"#id4\" title=\"Link to this heading\">#</a></h2><p>\u547d\u4ee4\u884c\u6a21\u5f0f\u4e0b\u4f1a\u81ea\u52a8\u8c03\u7528 <code class=\"docutils literal notranslate\"><span class=\"pre\">profiler.start</span></code> \u548c <code class=\"docutils literal notranslate\"><span class=\"pre\">profiler.finalize</span></code>\uff0c\u4e14\u53ea\u652f\u6301\u5355\u4e2a session\u3002\u5929\u6570/ixKN \u5de5\u4f5c\u6d41\u8bf7\u4f7f\u7528 <code class=\"docutils literal notranslate\"><span class=\"pre\">flagtree-profiler</span> <span class=\"pre\">--ixkn</span></code> \u5305\u88c5\u5668\uff0c\u56e0\u4e3a ixKN \u9700\u8981\u4ece\u8fdb\u7a0b\u542f\u52a8\u65f6\u5f00\u59cb\u5206\u6790\u76ee\u6807\u8fdb\u7a0b\u3002</p>", "a[href=\"#profiler\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Profiler<a class=\"headerlink\" href=\"#profiler\" title=\"Link to this heading\">#</a></h1><p>FlagTree Profiler \u662f\u9762\u5411 Triton \u7684\u8f7b\u91cf\u7ea7\u6027\u80fd\u5206\u6790\u5668\uff0c\u63d0\u4f9b\u4ece Python \u8c03\u7528\u7684 GPU kernel \u7684\u7a0b\u5e8f\u4e0a\u4e0b\u6587\u3001metadata \u548c\u786c\u4ef6\u6027\u80fd\u6307\u6807\uff0c\u5e76\u5c06\u8bb0\u5f55\u805a\u5408\u4e3a\u8c03\u7528\u6811\u3001\u65f6\u95f4\u7ebf\u3001Hatchet\u3001\u5143\u6570\u636e\u53ca\u5382\u5546\u76f8\u5173\u8f93\u51fa\u3002</p>", "a[href=\"#id1\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u57fa\u672c\u7528\u6cd5<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h2><p>\u5206\u6790\u4e00\u4e2a\u51fd\u6570\uff1a</p>", "a[href=\"#id2\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u540e\u7aef\u4e0e\u6a21\u5f0f<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h2><p>FlagTree Profiler \u652f\u6301\u4e03\u4e2a\u540e\u7aef\uff1a</p>", "a[href=\"#instrumentation\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Instrumentation<a class=\"headerlink\" href=\"#instrumentation\" title=\"Link to this heading\">#</a></h3><p><code class=\"docutils literal notranslate\"><span class=\"pre\">instrumentation</span></code> \u540e\u7aef\u63d0\u4f9b\u7ec6\u7c92\u5ea6\u7684 kernel \u5185\u5206\u6790\uff0c\u751f\u6210 trace \u6216 tree \u89c6\u56fe\uff0c\u9ed8\u8ba4\u5206\u6790 kernel cycles\uff0c\u53ef\u80fd\u9700\u8981\u5171\u4eab\u5185\u5b58\u3002DSL \u7ea7\u63d2\u6869\u9ed8\u8ba4\u53ea\u652f\u6301 Gluon kernel\uff1b\u9ad8\u9636\u7528\u6237\u53ef\u6539\u4e3a\u5bf9 <code class=\"docutils literal notranslate\"><span class=\"pre\">ttir</span></code> \u6216 <code class=\"docutils literal notranslate\"><span class=\"pre\">ttgir</span></code> IR \u63d2\u6869\u3002</p>", "a[href=\"#scope\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Scope \u4e0e\u6307\u6807<a class=\"headerlink\" href=\"#scope\" title=\"Link to this heading\">#</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">python</span></code> \u4e0a\u4e0b\u6587\u62a5\u544a\u6bcf\u4e2a GPU kernel \u88ab\u8c03\u7528\u7684\u6587\u4ef6\u3001\u51fd\u6570\u548c\u884c\u53f7\uff1b<code class=\"docutils literal notranslate\"><span class=\"pre\">shadow</span></code> \u4e0a\u4e0b\u6587\u62a5\u544a\u7528\u6237\u6807\u6ce8\u7684\u533a\u57df\uff1a</p>", "a[href=\"#id6\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u73af\u5883\u53d8\u91cf<a class=\"headerlink\" href=\"#id6\" title=\"Link to this heading\">#</a></h2><p>\u8fd0\u884c\u65f6\u73af\u5883\u53d8\u91cf\u4f7f\u7528 <code class=\"docutils literal notranslate\"><span class=\"pre\">FLAGTREE_PROFILER_*</span></code> \u524d\u7f00\u3002\u516c\u5f00 Python \u5165\u53e3\u4e3a <code class=\"docutils literal notranslate\"><span class=\"pre\">flagtree.profiler</span></code>\uff0cnative \u6a21\u5757\u4e3a <code class=\"docutils literal notranslate\"><span class=\"pre\">flagtree.profiler._native</span></code>\uff1bCLI \u5de5\u5177\u4e3a <code class=\"docutils literal notranslate\"><span class=\"pre\">flagtree-profiler</span></code> \u548c <code class=\"docutils literal notranslate\"><span class=\"pre\">flagtree-profiler-viewer</span></code>\u3002</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
